import type { ErrorInfo } from "../shared/types.js";
import type { IJobExecutionHandle, Job } from "./types.js";
import { JobQueueState } from "./types.js";

/**
 * Implementation of the IJobExecutionHandle interface
 */
export class JobExecutionHandle implements IJobExecutionHandle {
  private _state: JobQueueState;
  private _job: Job;
  private onStart?: () => void;
  private onComplete?: () => void;
  private onFail?: (error: ErrorInfo) => void;
  private onDefer?: () => void;

  private getStateName(state: JobQueueState): string {
    switch (state) {
      case JobQueueState.PREPROCESSING:
        return "PREPROCESSING";
      case JobQueueState.PENDING:
        return "PENDING";
      case JobQueueState.READY:
        return "READY";
      case JobQueueState.RUNNING:
        return "RUNNING";
      case JobQueueState.RESOLVED:
        return "RESOLVED";
      default:
        return `UNKNOWN`;
    }
  }

  constructor(
    job: Job,
    initialState: JobQueueState,
    callbacks?: {
      onStart?: () => void;
      onComplete?: () => void;
      onFail?: (error: ErrorInfo) => void;
      onDefer?: () => void;
    },
  ) {
    this._job = job;
    this._state = initialState;
    this.onStart = callbacks?.onStart;
    this.onComplete = callbacks?.onComplete;
    this.onFail = callbacks?.onFail;
    this.onDefer = callbacks?.onDefer;
  }

  get job(): Job {
    return this._job;
  }

  get state(): JobQueueState {
    return this._state;
  }

  start(): void {
    if (this._state !== JobQueueState.READY) {
      throw new Error(
        `Cannot start job in state ${this.getStateName(this._state)}`,
      );
    }
    this._state = JobQueueState.RUNNING;
    this.onStart?.();
  }

  complete(): void {
    if (this._state !== JobQueueState.RUNNING) {
      throw new Error(
        `Cannot complete job in state ${this.getStateName(this._state)}`,
      );
    }
    this._state = JobQueueState.RESOLVED;
    this.onComplete?.();
  }

  fail(error: ErrorInfo): void {
    if (this._state !== JobQueueState.RUNNING) {
      throw new Error(
        `Cannot fail job in state ${this.getStateName(this._state)}`,
      );
    }
    this._state = JobQueueState.RESOLVED;
    this.onFail?.(error);
  }

  defer(): void {
    if (this._state !== JobQueueState.RUNNING) {
      throw new Error(
        `Cannot defer job in state ${this.getStateName(this._state)}`,
      );
    }
    this._state = JobQueueState.RESOLVED;
    this.onDefer?.();
  }
}
